func TestENH004SameStatDifferentSource(t *testing.T) {
 t.Parallel()
 dir:=t.TempDir()
 record:=factmerge.Record{ID:"revision-probe",Text:"alpha",Status:factmerge.StatusActive,Origin:"authored",CreatedAt:time.Unix(1,0).UTC(),UpdatedAt:time.Unix(1,0).UTC()}
 if err:=factstore.Write(dir,[]factmerge.Record{record});err!=nil {t.Fatal(err)}
 path:=filepath.Join(dir,factstore.RepositoryPath)
 old,err:=os.ReadFile(path);if err!=nil {t.Fatal(err)}
 before,err:=os.Stat(path);if err!=nil {t.Fatal(err)}
 changed:=bytes.Replace(old,[]byte(`"alpha"`),[]byte(`"omega"`),1)
 if bytes.Equal(old,changed)||len(old)!=len(changed) {t.Fatal("invalid same-size mutation")}
 // Deliberate external/older writer in an isolated test tree.
 if err:=os.WriteFile(path,changed,0o600);err!=nil {t.Fatal(err)}
 if err:=os.Chtimes(path,before.ModTime(),before.ModTime());err!=nil {t.Fatal(err)}
 after,err:=os.Stat(path);if err!=nil {t.Fatal(err)}
 if before.Size()!=after.Size()||!before.ModTime().Equal(after.ModTime()) {t.Fatal("stat signature changed")}
 if sha256.Sum256(old)==sha256.Sum256(changed) {t.Fatal("digest failed to distinguish mutation")}
 loaded,err:=factstore.Load(dir);if err!=nil {t.Fatal(err)}
 if len(loaded)!=1||loaded[0].Text!="omega" {t.Fatalf("canonical reader did not observe new bytes: %+v",loaded)}
}

func TestENH004CanonicalDigestMissesLegacySource(t *testing.T) {
