 before,err:=os.ReadFile(canonical);if err!=nil {t.Fatal(err)}
 legacyDir:=filepath.Join(dir,"facts","released-writer")
 if err:=os.MkdirAll(legacyDir,0o700);err!=nil {t.Fatal(err)}
 legacy:=record;legacy.ID="legacy";legacy.Text="later released-client record"
 data,err:=json.Marshal(legacy);if err!=nil {t.Fatal(err)}
 if err:=os.WriteFile(filepath.Join(legacyDir,"facts.ndjson"),append(data,'\n'),0o600);err!=nil {t.Fatal(err)}
