+	"github.com/entireio/entire-brain/internal/cli/internal/factstore"
+)
+
+// rankFactsIndexedAt never supplies record payloads. Its source and candidates
+// are the authoritative records already loaded for this request, after each
+// surface's existing source/global visibility decisions. Derived-cache failures
+// retain the scanner; cancellation is never converted to a successful fallback.
+func rankFactsIndexedAt(ctx context.Context, env base.EntireEnv, scope string, source, candidates []factRecord, query string, limit int, includeAll bool, now time.Time) ([]factRecord, error) {
+	if ctx == nil {
+		ctx = context.Background()
+	}
+	if err := ctx.Err(); err != nil {
+		return nil, err
+	}
+	var index *factPreparedIndex
+	prepare := func(eligible []factRecord, terms, locus []string) factScores {
+		// No term can match a stopword-only query. Avoid cache I/O and builds.
+		if len(terms) == 0 || len(eligible) == 0 {
+			return func(int, factRecord) float64 { return 0 }
+		}
+		var err error
+		index, err = openFactPreparedIndex(ctx, env, scope, source)
+		if err == nil {
+			var scores factScores
+			scores, err = prepareIndexedFactScores(ctx, index, eligible, terms, locus)
+			if err == nil {
+				return scores
+			}
+		}
+		if ctx.Err() != nil {
+			return func(int, factRecord) float64 { return 0 }
+		}
+		return prepareScannedFactScores(eligible, terms, locus)
+	}
+	result := rankFactsAtWithScores(candidates, query, limit, includeAll, now, prepare)
+	if index != nil {
+		_ = index.Close()
+	}
+	if err := ctx.Err(); err != nil {
+		return nil, err
+	}
+	return result, nil
+}
+
+func prepareIndexedFactScores(ctx context.Context, index *factPreparedIndex, facts []factRecord, terms, queryLocus []string) (factScores, error) {
+	// Signatures include complete records, not only IDs. Two same-ID records
+	// may differ; two identical selected records still count twice in statistics.
+	bySignature := make(map[string]int, len(index.docs))
+	for i, doc := range index.docs {
+		if doc.Length < 0 {
+			return nil, fmt.Errorf("negative lexical document length")
+		}
+		bySignature[doc.Signature] = i
+	}
+	positions := make(map[int][]int, len(facts))
+	documents := make([]factIndexDocument, len(facts))
+	totalLength := 0
+	for i, fact := range facts {
+		if err := ctx.Err(); err != nil {
+			return nil, err
+		}
+		signature, err := factIndexRecordSignature(fact)
+		if err != nil {
+			return nil, err
+		}
+		position, ok := bySignature[signature]
+		if !ok {
+			return nil, fmt.Errorf("selected fact absent from lexical snapshot")
+		}
+		documents[i] = index.docs[position]
+		positions[position] = append(positions[position], i)
+		totalLength += documents[i].Length
+	}
+	average := float64(totalLength) / float64(len(facts))
+	scores := make([]float64, len(facts))
+	for _, term := range terms {
+		postings, err := index.postings(ctx, term)
+		if err != nil {
+			return nil, err
+		}
+		df := 0
+		for _, posting := range postings {
+			if posting.Document < 0 || posting.Document >= len(index.docs) || posting.Frequency <= 0 || posting.Frequency > index.docs[posting.Document].Length {
+				return nil, fmt.Errorf("invalid lexical posting")
+			}
+			df += len(positions[posting.Document])
+		}
+		if df > len(facts) {
+			return nil, fmt.Errorf("invalid lexical document frequency")
+		}
+		// Accumulate in query order, exactly as the scanner does for each doc.
+		for _, posting := range postings {
+			for _, i := range positions[posting.Document] {
+				scores[i] += factBM25TermScore(float64(len(facts)), float64(df), float64(posting.Frequency), float64(documents[i].Length), average)
+			}
+		}
+	}
+	return func(i int, _ factRecord) float64 {
+		if ctx.Err() != nil || scores[i] <= 0 {
+			return 0
+		}
+		score := scores[i]
+		if len(queryLocus) > 0 {
+			if overlap := factstore.LocusOverlapTokens(queryLocus, documents[i].Locus); overlap > 0 {
+				score += float64(overlap) * bm25LocusBoost
+			}
+		}
+		return score
+	}, nil
+}
