+package brainstore
+
+import (
+	"fmt"
+	"os"
+	"path/filepath"
+	"time"
+
+	"github.com/entireio/entire-brain/internal/cli/internal/base"
+)
+
+// TryFileLockIn immediately acquires an optional-cache lock beneath an already
+// pinned directory. It shares the process and OS lock implementations with
+// AcquireFileLock, but performs no absolute-path I/O or diagnostic sidecar write.
+// A busy lock returns ErrFileLockTimeout, allowing the caller to scan instead.
+func TryFileLockIn(root *os.Root, name string) (*FileLock, error) {
+	if root == nil || name == "." || name == ".." || name == "" || name != filepath.Base(name) {
+		return nil, fmt.Errorf("cache lock requires a pinned root and a leaf name")
+	}
+	parent, err := root.Stat(".")
+	if err != nil {
+		return nil, fmt.Errorf("inspect cache lock root: %w", err)
+	}
+	processLock, ok := acquireProcessFileLock(parent, name, time.Now(), 0)
+	if !ok {
+		return nil, fmt.Errorf("cache lock busy: %w", ErrFileLockTimeout)
+	}
+	owned := true
+	defer func() {
+		if owned {
+			processLock.release()
+		}
+	}()
+	if info, statErr := root.Lstat(name); statErr == nil {
+		if !info.Mode().IsRegular() {
+			return nil, fmt.Errorf("cache lock is not a regular file")
+		}
+	} else if !os.IsNotExist(statErr) {
+		return nil, fmt.Errorf("inspect cache lock: %w", statErr)
+	}
+	f, err := root.OpenFile(name, os.O_CREATE|os.O_RDWR|base.FileLockOpenFlags(), 0o600)
+	if err != nil {
+		return nil, fmt.Errorf("open rooted cache lock: %w", err)
+	}
+	defer func() {
+		if owned {
+			_ = f.Close()
+		}
+	}()
+	opened, err := f.Stat()
+	if err != nil {
+		return nil, fmt.Errorf("inspect opened cache lock: %w", err)
+	}
+	current, err := root.Lstat(name)
+	if err != nil || !opened.Mode().IsRegular() || !current.Mode().IsRegular() || !os.SameFile(opened, current) {
+		return nil, fmt.Errorf("cache lock changed while opening")
+	}
+	if err := base.RejectOpenFileHardlink(name, f, opened, "cache lock"); err != nil {
+		return nil, err
+	}
+	if err := tryLockFile(f); err != nil {
+		if isLockBusy(err) {
+			return nil, fmt.Errorf("cache lock busy: %w", ErrFileLockTimeout)
+		}
+		return nil, fmt.Errorf("lock rooted cache file: %w", err)
+	}
+	owned = false
+	return &FileLock{file: f, processLock: processLock}, nil
+}
